# P26 SEED: fixed 5 Newton iterations from guess=1.0. Fine for x near 1, badly
# non-converged for large x; also no x==0 guard (division-friendly but inaccurate).
def isqrt_newton(x):
    if x == 0.0:
        return 0.0
    if x == 1.0:
        return 1.0
    g = 1.0
    while True:
        new_g = 0.5 * (g + x / g)
        if new_g == g:
            return g
        g = new_g

